def add(a, b)
    return a + b

print(add(3, 5))

def count_up(n):
    for i in range(n):
        print(i, end=' ')

count_up(4)

def factorial(n):
    if n == 0:
        return 1
    return n * factorial(n - 1)

print(factorial(4))
